import Foundation

public enum ClipboardRules {
    /// Standard NSPasteboard markers used by password managers & macOS to mark sensitive data
    public static let confidentialTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "com.agilebits.onepassword",
        "com.typeit4me.clipping",
        "de.petermaurer.TransientPasteboardType"
    ]

    /// Standard NSPasteboard markers for transient or auto-generated clipboard writes
    public static let transientTypes: Set<String> = [
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.clipshelf.internal"
    ]

    /// Evaluates whether a clipboard event should be ignored based on user rules.
    public static func shouldIgnore(
        pasteboardTypes: Set<String>,
        sourceBundleID: String?,
        settings: AppSettings
    ) -> Bool {
        if settings.isPaused {
            return true
        }

        if let sourceBundleID,
           settings.ignoredApps.contains(where: { $0.bundleID.caseInsensitiveCompare(sourceBundleID) == .orderedSame }) {
            return true
        }

        if settings.ignoreConfidential && !pasteboardTypes.isDisjoint(with: confidentialTypes) {
            return true
        }

        if settings.ignoreTransient && !pasteboardTypes.isDisjoint(with: transientTypes) {
            return true
        }

        return false
    }

    /// Detects if a trimmed string is a pure hex color literal (#RGB, #RRGGBB, #RRGGBBAA).
    public static func normalizedHexColor(from text: String) -> String? {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed.hasPrefix("#") else { return nil }
        let hex = String(trimmed.dropFirst())
        guard hex.count == 3 || hex.count == 6 || hex.count == 8 else { return nil }
        let validHex = CharacterSet(charactersIn: "0123456789abcdefABCDEF")
        guard hex.unicodeScalars.allSatisfy({ validHex.contains($0) }) else { return nil }
        if hex.count == 3 {
            let expanded = hex.map { "\($0)\($0)" }.joined()
            return "#\(expanded.uppercased())"
        }
        return "#\(hex.uppercased())"
    }

    /// Detects if a trimmed string is a standalone http/https URL.
    public static func normalizedWebURL(from text: String) -> URL? {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.contains(" "), !trimmed.contains("\n") else { return nil }
        guard let url = URL(string: trimmed),
              let scheme = url.scheme?.lowercased(),
              (scheme == "http" || scheme == "https"),
              let host = url.host,
              host.contains(".") else {
            return nil
        }
        return url
    }
}
